style.css:
/* Discord – Dreamy Italics */

:root {
  --my-font: "Arial", sans-serif; /* Swap font here */
}

/* give Discord text the italic aesthetic */
body,
button,
input,
textarea,
[class*="message"],
[class*="username"],
[class*="channelName"],
[class*="markup"] {
  font-family: var(--my-font) !important;
  font-style: italic !important;
}
